#pragma once
#include "kstationStartupAdcTask.h"
#include "kstationNativeAdc.h"
#include "kstationNativeMidiPump.h"
#include <variant>
namespace kstation {
class NativeStartupAdc final {
 using A=StartupAdcTask;using S=StartupAdcStartTask;using C=StartupAdcSnapshotTask;using Q=StartupAdcQueueTask;struct Job{std::variant<A,S,C,Q>task;};
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x54a,0x5cc},{0x638,0x65a}}};bool active()const{return depth_||muxActive_;}void reset(){depth_=0;muxActive_=false;steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(at>=0x65a&&at<0x670){if(at==0x65a&&!muxActive_){mux_=NativeAdcMux{};muxActive_=true;}if(!muxActive_||!mux_.step(c))return false;muxActive_=!mux_.complete();++steps_;return true;}if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x54a)j.task.emplace<A>();else if(at==0x638)j.task.emplace<S>();else if(at==0x5a0)j.task.emplace<C>();else if(at==0x58c)j.task.emplace<Q>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup ADC capacity");jobs_[depth_++]=j;}
 auto&j=jobs_[depth_-1];std::visit([](auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,A>||std::is_same_v<V,S>)if(t.awaiting())t.resume();},j.task);if(at!=boundary(j))throw std::logic_error("Native K startup ADC boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
 std::visit([&](auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,A>)t.advanceBefore(cost,cr,[&]{c.reg8(8)=c.read8(0xc490);val(c,c.reg8(8));return uint8_t(c.reg8(8));},[&](unsigned value){val(c,c.reg8(8));c.write8(int8_t(value),0xc490);});else if constexpr(std::is_same_v<V,S>)t.advanceBefore(cost,cr,[&]{c.reg8(8)=c.read8(0xc490);val(c,c.reg8(8));return uint8_t(c.reg8(8));},[&](bool control,unsigned value){val(c,c.reg8(8));c.write8(int8_t(value),control?0xffffe8:0xc490);});else if constexpr(std::is_same_v<V,C>)t.advanceBefore(cost,cr,[&](unsigned index){c.reg16(9)=int16_t(c.read16(int(0xc410+2*index)));val(c,c.reg16(9));return uint16_t(c.reg16(9));},[&](bool armed,unsigned index,unsigned value){if(armed){c.write8(int8_t(value),int(0xc450+2*index));val(c,c.reg8(1));}else{c.write16(int16_t(value),int(0xc3d0+2*index));val(c,c.reg16(9));}});else t.advanceBefore(cost,cr,[&](bool producer,unsigned value){val(c,c.reg16(0));c.write16(int16_t(value),producer?0xc1cc:0xc1ce);});},j.task);
 if(c.cycles-begin!=cost)throw std::logic_error("Native K startup ADC clocks differ");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static bool waiting(const Job&j){return std::visit([](const auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,A>||std::is_same_v<V,S>)return t.awaiting();else return false;},j.task);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void dec(Stage1Cpu&c,unsigned r,bool word){int old=word?c.reg16(r):c.reg8(r),v=old-1;val(c,v);if((old&~v)&(word?0x8000:128))c.ccr|=2;if(word)c.reg16(r)=int16_t(v);else c.reg8(r)=int8_t(v);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,A>){static constexpr unsigned a[]={0x54a,0x54c,0x552,0x554,0x556,0x55a,0x55c,0x560,0x562,0x566,0x568,0x56a,0x56c,0x56e,0x570,0x572,0x578,0x57a,0x57c,0x57e,0x580,0x582,0x586,0x58a,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<V,S>){static constexpr unsigned a[]={0x638,0x63a,0x63c,0x642,0x644,0x646,0x648,0x64e,0x650,0x652,0x654,0x656,0x658,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<V,C>){static constexpr unsigned a[]={0x5a0,0x5a4,0x5a8,0x5ae,0x5b0,0x5b2,0x5b6,0x5b8,0x5bc,0x5be,0x5c0,0x5c2,0x5c6,0x5ca,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x58c,0x58e,0x590,0x596,0x59c,0x59e,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){switch(boundary(j)){case 0x54c:case 0x572:case 0x590:case 0x596:case 0x5a8:case 0x63c:case 0x648:return 6;case 0x556:case 0x55c:case 0x562:case 0x582:case 0x586:case 0x5a0:case 0x5a4:case 0x5b2:case 0x5b8:case 0x5c2:case 0x5c6:return 4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<A>(&j.task)){cr.read=bus(0xc490,1,last);cr.write=bus(0xc490,1,c.writeHistory());}else if(auto*t=std::get_if<S>(&j.task)){cr.read=bus(0xc490,1,last);cr.write=bus(t->stage()==S::Stage::WriteControl?0xffffe8:0xc490,1,c.writeHistory());}else if(auto*t=std::get_if<C>(&j.task)){cr.read=bus(0xc410+2*t->index(),2,last);cr.write=t->stage()==C::Stage::WriteArmed?bus(0xc450+2*t->index(),1,c.writeHistory()):bus(0xc3d0+2*t->index(),2,c.writeHistory());}else if(auto*t=std::get_if<Q>(&j.task))cr.write=bus(t->stage()==Q::Stage::WriteProducer?0xc1cc:0xc1ce,2,c.writeHistory());return cr;}
 static void project(Job&j,Stage1Cpu&c){std::visit([&](const auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,A>){using T=A::Stage;switch(t.stage()){case T::IdleValue:c.reg8(8)=32;val(c,32);break;case T::Passes:c.reg8(8)=16;val(c,16);break;case T::RetainPass:case T::RetainDelay:case T::RetainInner:push(c,0,true);break;case T::StartGroup:midi_projection::call(c,0x638,0x55a,true);break;case T::Settling:c.reg16(0)=1;val(c,1);break;case T::Delay:c.reg16(0)=2663;val(c,2663);break;case T::DecrementDelay:case T::DecrementSettling:dec(c,0,true);break;case T::RestoreInner:case T::RestoreDelay:case T::RestorePass:pop(c,0,true);break;case T::CompareGroup:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(8)),28,8,true);break;case T::DecrementPass:dec(c,8,false);break;case T::Snapshot:midi_projection::call(c,0x5a0,0x586,true);break;case T::ClearQueue:midi_projection::call(c,0x58c,0x58a,true);break;case T::Return:midi_projection::ret(c);break;default:break;}}
 else if constexpr(std::is_same_v<V,S>){using T=S::Stage;switch(t.stage()){case T::RetainValue:push(c,0,true);break;case T::RetainScratch:push(c,1,true);break;case T::CompareGroup:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(8)),28,8,true);break;case T::ClearGroup:c.reg8(8)=0;val(c,0);break;case T::Mux:midi_projection::call(c,0x65a,0x650,false);break;case T::Control:c.reg8(8)=0x73;val(c,0x73);break;case T::RestoreScratch:pop(c,1,true);break;case T::RestoreValue:pop(c,0,true);break;case T::Return:midi_projection::ret(c);break;default:break;}}
 else if constexpr(std::is_same_v<V,C>){using T=C::Stage;switch(t.stage()){case T::RetainPointer:push(c,0,false);break;case T::RetainValue:push(c,1,false);break;case T::Bind:c.reg32(0)=0xc3d0;val(c,c.reg32(0));break;case T::Count:c.reg8(9)=32;val(c,32);break;case T::Arm:c.reg8(1)=1;val(c,1);break;case T::Advance:{int old=c.reg32(0),v=old+2;val(c,v);if((~old&v)&int(0x80000000))c.ccr|=2;c.reg32(0)=v;break;}case T::Decrement:dec(c,9,false);break;case T::RestoreValue:pop(c,1,false);break;case T::RestorePointer:pop(c,0,false);break;case T::Return:midi_projection::ret(c);break;default:break;}}
 else{using T=Q::Stage;switch(t.stage()){case T::Retain:push(c,0,true);break;case T::Clear:c.reg16(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case T::Restore:pop(c,0,true);break;case T::Return:midi_projection::ret(c);break;default:break;}}},j.task);}
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeAdcMux mux_;bool muxActive_=false;
};
}
